algorithms.pseudocode:
def process(event):
    if not bloom.might_contain(event.id):
        bloom.add(event.id); seen.put(event.id, now); emit(event); return
    if seen.get(event.id) is not None:
        metrics.dup += 1; return          # true duplicate
    seen.put(event.id, now); bloom.add(event.id); emit(event)
# seen has TTL 24h; bloom rotated hourly as a ring of 24 filters
